// Will be replaced in post-build with the paths generated by SSG
// TODO calculate this at build time from the SSG configuration
/**
 * A set of static paths generated by the SSG, including loader json. Routes always have a trailing
 * slash, short for `.../index.html`
 */
export const staticPaths = new Set(['__QWIK_ROUTER_STATIC_PATHS_ARRAY__']);

/**
 * Check if the current pathname needs a redirect due to trailing slash mismatch. If we're not sure,
 * we fall through.
 *
 * Note that we ignore build/ and assets/, those never need trailing slash redirects.
 *
 * @returns The canonical path with the correct trailing slash if a redirect is needed, otherwise
 *   `undefined`.
 */
export function getStaticPathRedirect(method: string, url: URL) {
  const { pathname, search } = url;
  if (
    method.toUpperCase() !== 'GET' ||
    pathname === '/' ||
    !pathname.startsWith('/') ||
    // Protocol-relative URLs are not valid, so don't redirect them. This is a security measure to avoid redirecting to an unexpected origin.
    pathname.startsWith('//')
  ) {
    return;
  }
  const hasTrailingSlash = pathname.endsWith('/');
  const routesHaveTrailingSlash = !globalThis.__NO_TRAILING_SLASH__;
  if (hasTrailingSlash === routesHaveTrailingSlash) {
    return;
  }
  // The current trailing slash is wrong, fix it
  const canonicalPathname = hasTrailingSlash ? pathname.slice(0, -1) : pathname + '/';
  if (
    staticPaths.has(canonicalPathname) ||
    // foo.json/ => foo.json
    (!routesHaveTrailingSlash && staticPaths.has(pathname))
  ) {
    // Fixed trailing slash is a static path, so redirect to it
    return canonicalPathname + search;
  }
}

/**
 * Decide whether a given request path is a static path, for optimizing file access.
 *
 * @internal
 */
export function isStaticPath(method: string, url: URL) {
  method = method.toUpperCase();
  if (method !== 'GET' && method !== 'HEAD') {
    return false;
  }
  const p = url.pathname;
  if (p.startsWith('/' + (globalThis.__QWIK_BUILD_DIR__ || 'build') + '/')) {
    return true;
  }
  if (p.startsWith('/' + (globalThis.__QWIK_ASSETS_DIR__ || 'assets') + '/')) {
    return true;
  }
  // Loader json files are listed only when SSG wrote them, so a missing one falls through to SSR.
  if (globalThis.__NO_TRAILING_SLASH__ && p !== '/') {
    return !p.endsWith('/') && (staticPaths.has(p) || staticPaths.has(p + '/'));
  }
  return staticPaths.has(p);
}
